let loaded,pending;
const waiting=new WeakMap();
export const chamberThermistorPrepared=()=>!!loaded;
export function prepareChamberThermistor(){if(loaded)return Promise.resolve(loaded);if(!pending)pending=import('./chamber-service-owner.js').then(async m=>{await m.prepareChamberServiceAssets();return loaded=m;}).catch(error=>{pending=undefined;throw error;});return pending;}
export function cancelChamberThermistorWait(viewer){const token=waiting.get(viewer);if(!token)return;waiting.delete(viewer);token.feedback.finish();}
export function waitForChamberThermistor(viewer,{isCurrent,ready,failed,indicator}){if(loaded)return true;if(waiting.has(viewer))return false;const feedback=indicator(),token={feedback};waiting.set(viewer,token);prepareChamberThermistor().then(()=>{if(waiting.get(viewer)===token&&isCurrent())ready();}).catch(error=>{if(waiting.get(viewer)===token&&isCurrent())failed(error);}).finally(()=>{if(waiting.get(viewer)===token)waiting.delete(viewer);feedback.finish();});return false;}
export function prepareChamberThermistorScene(viewer,spec,task){if(task.chamberThermistor){if(!loaded)throw Error('Chamber service assets are not ready');const o=loaded.ensureChamberServiceOwner(viewer);o.handlingEnabled=!!spec.plan.chamberProbeHandling;o.claimTask(task.id);for(const [id,state]of o.restStates)if(!Object.hasOwn(spec.flexStates,id))spec.flexStates[id]=state;if(!o.enable(true))throw Error(o.refusal||'Chamber owner retired');}else leaveChamberThermistor(viewer);return spec;}
export function leaveChamberThermistor(viewer){const o=viewer.chamberServiceOwner;if(o?.active)o.enable(false);}
